# ── Hero with centered robot ──
st.markdown(f"""
<div class="hero">
    <img class="hero-robot" src="data:image/png;base64,{ROBOT_B64}" alt="FoodWise Robot"/>
    <h1>FoodWise AI</h1>
    <p>Intelligent answers on food waste — reduction, composting, policy &amp; more.</p>
</div>
""", unsafe_allow_html=True)

@st.cache_resource(show_spinner=False)
def load_chain():
    embeddings = HuggingFaceEmbeddings(model_name="sentence-transformers/all-MiniLM-L6-v2")
    vectorstore = FAISS.load_local("vector_db", embeddings, allow_dangerous_deserialization=True)
    retriever = vectorstore.as_retriever(search_kwargs={"k": 4})
    llm = ChatOllama(model="llama3", temperature=0)
    return retriever, llm

with st.spinner("Loading knowledge base…"):
    retriever, llm = load_chain()

st.markdown('<span class="input-label">Your question</span>', unsafe_allow_html=True)
query = st.text_input(label="q", placeholder="e.g. How can restaurants reduce food waste?", label_visibility="collapsed")
ask = st.button("Ask →")

if not query:
    st.markdown("""
    <div class="hints-row">
        <div class="hint-card"><div class="hicon">🥦</div><div class="hlabel">Reducing household food waste</div></div>
        <div class="hint-card"><div class="hicon">🏪</div><div class="hlabel">Supermarket surplus solutions</div></div>
        <div class="hint-card"><div class="hicon">♻️</div><div class="hlabel">Composting best practices</div></div>
    </div>
    """, unsafe_allow_html=True)

if query and ask:
    with st.spinner("Searching knowledge base…"):
        docs = retriever.invoke(query)
        context = "\n\n".join([doc.page_content for doc in docs])
    with st.spinner("Generating answer…"):
        response = llm.invoke(f"""You are a helpful assistant specialising in food waste reduction.
Use only the provided context to answer. Be concise and practical.

Context:
{context}

Question: {query}

Answer:""")

    answer_html = response.content.replace("\n", "<br>")
    st.markdown(f"""
    <div class="answer-card">
        <div class="answer-badge">✦ Answer</div>
        <div class="answer-text">{answer_html}</div>
    </div>
    """, unsafe_allow_html=True)

    if docs:
        items_html = ""
        for i, doc in enumerate(docs, 1):
            src = doc.metadata.get("source", f"Document {i}")
            snippet = doc.page_content[:110].replace("<","&lt;").replace(">","&gt;")
            items_html += f'<div class="source-item"><span class="source-num">{i}</span><strong>{src}</strong> — {snippet}…</div>'
        st.markdown(f'<div class="sources-box"><div class="sources-title">📄 Retrieved sources</div>{items_html}</div>', unsafe_allow_html=True)

st.markdown('<div class="footer">Powered by LLaMA 3 · FAISS · LangChain · Streamlit</div>', unsafe_allow_html=True)